#include <iostream>
using namespace std;

template <typename T>
void label(T x) {
    cout << "通用那一份" << endl;
}

template <>
void label<const char*>(const char* x) {
    cout << "小灶那一份：" << x << endl;
}

int main() {
    label("{w}");
    return 0;
}
